import sys

def find_answer(n, a):
    res = 0
    cur = 0
    k = -1
    for i in range(n):
        cur += a[i]
        if cur < 0:
            cur = 0
            k = i
        res = max(res, (i - k) * cur)
    return res

def correct_answer(n, a):
    max_sum = float('-inf')
    for l in range(n):
        current_sum = 0
        for r in range(l, n):
            current_sum += a[r]
            max_sum = max(max_sum, current_sum * (r - l + 1))
    return max_sum

